package android.content;
public final class Intent {public static final String ACTION_INSERT="android.intent.action.INSERT",EXTRA_EMAIL="android.intent.extra.EMAIL";public final String action;public android.net.Uri data;public final java.util.Map<String,Object> extras=new java.util.HashMap<>();public Intent(String action){this.action=action;}public Intent setData(android.net.Uri value){data=value;return this;}public Intent putExtra(String key,String value){extras.put(key,value);return this;}public Intent putExtra(String key,long value){extras.put(key,value);return this;}public Intent putExtra(String key,boolean value){extras.put(key,value);return this;}}
